mapper.select:
SELECT e.ID AS id, e.INSTANCE_ID AS instanceId, e.EVENT_TYPE AS eventType, e.NODE_ID AS nodeId, e.EVENT_TIME_MS AS eventTimeMs, e.EVENT_DATA_JSON AS eventDataJson, e.TRACE_ID AS traceId, e.ENV_CODE AS envCode, e.DELETED AS deleted, e.CREATE_USER AS createUser, e.CREATE_TIME AS createTime, e.UPDATE_USER AS updateUser, e.UPDATE_TIME AS updateTime FROM AST_FLOW_INSTANCE_EVENT e WHERE (e.DELETED = 0 OR e.DELETED IS NULL)
AND e.INSTANCE_ID = #{req.instanceId}
AND e.EVENT_TYPE = #{req.eventType}
AND e.NODE_ID LIKE CONCAT('%', #{req.nodeId}, '%')
AND e.TRACE_ID = #{req.traceId}
AND e.ENV_CODE = #{req.envCode}
ORDER BY e.UPDATE_TIME DESC, e.ID DESC
